sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float threshold;
uniform float softness;
uniform float invert;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half keep = smoothstep(half(threshold), half(threshold + softness) + 0.0001, luma(unpremul(c).rgb));
    return c * (invert > 0.5 ? 1 - keep : keep);
}
